INT_PTR BatchExportDialog::Run(){struct Template{DLGTEMPLATE t{};WORD menu=0,cls=0,title=0;}r;r.t.style=WS_POPUP|WS_CAPTION|WS_SYSMENU|DS_MODALFRAME|WS_CLIPCHILDREN;r.t.cx=480;r.t.cy=320;InitModalIndirect(&r.t,owner_);return DoModal();}
BOOL BatchExportDialog::OnInitDialog(){CDialog::OnInitDialog();dpi_=LayoutDpi(m_hWnd);BindText(*this,Text::BatchExport);const DWORD style=WS_CHILD|WS_VISIBLE;auto label=[&](CStatic& c,Text key){c.Create(Tr(key),style,CRect(),this);BindText(c,key);};label(folderLabel_,Text::BatchFolder);label(nameLabel_,Text::BatchStem);label(formatLabel_,Text::BatchFormat);label(qualityLabel_,Text::JpegQuality);label(help_,Text::BatchReviewHelp);folder_.Create(style|WS_BORDER|WS_TABSTOP|ES_AUTOHSCROLL,CRect(),this,BatchFolderEdit);folder_.SetLimitText(1024);folder_.SetWindowText(plan.directory);name_.Create(style|WS_BORDER|WS_TABSTOP|ES_AUTOHSCROLL,CRect(),this,BatchNameEdit);name_.SetLimitText(100);quality_.Create(style|WS_BORDER|WS_TABSTOP|ES_NUMBER,CRect(),this,BatchQualityEdit);quality_.SetLimitText(3);CString quality;quality.Format(L"%d",plan.quality);quality_.SetWindowText(quality);format_.Create(style|WS_TABSTOP|CBS_DROPDOWNLIST,CRect(),this,BatchFormatChoice);for(auto x:{L"JPG",L"PNG",L"BMP"})format_.AddString(x);format_.SetCurSel(plan.format==L"png"?1:plan.format==L"bmp"?2:0);list_.Create(style|WS_BORDER|WS_TABSTOP|LVS_REPORT|LVS_SINGLESEL|LVS_SHOWSELALWAYS,CRect(),this,BatchList);list_.SetExtendedStyle(LVS_EX_CHECKBOXES|LVS_EX_FULLROWSELECT|LVS_EX_DOUBLEBUFFER);list_.InsertColumn(0,Tr(Text::BatchPages));list_.InsertColumn(1,Tr(Text::BatchOutputName));syncing_=true;for(size_t i=0;i<labels_.size();++i){CString stem=labels_[i];const int dot=stem.ReverseFind(L'.');if(dot>0)stem=stem.Left(dot);CString valid;for(wchar_t c:std::wstring(stem))if(c>=32&&!wcschr(L"<>:\"/\\|?*",c))valid+=c;valid=valid.Left(72);valid.Trim();if(valid.IsEmpty())valid=L"image";CString suffix;suffix.Format(L"_%02u",unsigned(i+1));names_.push_back(valid+suffix);list_.InsertItem(int(i),labels_[i]);list_.SetCheck(int(i),TRUE);}syncing_=false;
    auto button=[&](CButton& c,Text key,UINT id,DWORD extra=0){c.Create(Tr(key),style|WS_TABSTOP|extra,CRect(),this,id);BindText(c,key);};button(browse_,Text::BatchBrowse,Command::BatchBrowse);button(ok_,Text::BatchExport,IDOK,BS_DEFPUSHBUTTON);button(cancel_,Text::Cancel,IDCANCEL);ApplyFont(*this,font_);RefreshNames();Layout();CenterWindow(owner_);if(!names_.empty())Select(0);if(initAudit_){initAudit_(*this);EndDialog(IDCANCEL);return FALSE;}return TRUE;}
void BatchExportDialog::SaveName(){if(current_>=0&&current_<int(names_.size()))name_.GetWindowText(names_[current_]);}
void BatchExportDialog::Select(int index){SaveName();syncing_=true;current_=index;name_.SetWindowText(names_[index]);list_.SetItemState(index,LVIS_SELECTED|LVIS_FOCUSED,LVIS_SELECTED|LVIS_FOCUSED);list_.EnsureVisible(index,FALSE);syncing_=false;RefreshNames();}
void BatchExportDialog::RefreshNames(){const CString ext=format_.GetCurSel()==1?L".png":format_.GetCurSel()==2?L".bmp":L".jpg";for(size_t i=0;i<names_.size();++i)list_.SetItemText(int(i),1,names_[i]+ext);quality_.EnableWindow(format_.GetCurSel()==0);}
void BatchExportDialog::OnSelection(NMHDR*,LRESULT* result){*result=0;if(syncing_)return;const int row=list_.GetNextItem(-1,LVNI_SELECTED);if(row>=0&&row!=current_)Select(row);}
void BatchExportDialog::OnFormat(){SaveName();RefreshNames();}
void BatchExportDialog::OnBrowse(){CFolderPickerDialog dialog(nullptr,OFN_PATHMUSTEXIST|OFN_NOCHANGEDIR,this);if(dialog.DoModal()==IDOK)folder_.SetWindowText(dialog.GetPathName());}
void BatchExportDialog::OnOK(){SaveName();RefreshNames();services::BatchImagePlan candidate;folder_.GetWindowText(candidate.directory);candidate.format=format_.GetCurSel()==1?L"png":format_.GetCurSel()==2?L"bmp":L"jpg";CString value;quality_.GetWindowText(value);wchar_t* end=nullptr;candidate.quality=int(wcstol(value,&end,10));candidate.files.clear();for(size_t i=0;i<names_.size();++i)if(list_.GetCheck(int(i)))candidate.files.push_back({i,names_[i]});try{if(value.IsEmpty()||!end||*end)throw std::runtime_error("Invalid quality");services::BatchImagePaths(candidate,labels_.size());}catch(const std::exception&){MessageBox(Tr(Text::BatchInvalid),Tr(Text::BatchExport));return;}plan=std::move(candidate);CDialog::OnOK();}
void BatchExportDialog::Layout(){MONITORINFO monitor{sizeof(monitor)};GetMonitorInfo(MonitorFromWindow(m_hWnd,MONITOR_DEFAULTTONEAREST),&monitor);if(workAreaAudit_.cx>0&&workAreaAudit_.cy>0){monitor.rcWork.right=monitor.rcWork.left+workAreaAudit_.cx;monitor.rcWork.bottom=monitor.rcWork.top+workAreaAudit_.cy;}const int gap=Px(m_hWnd,12),row=Px(m_hWnd,30),bw=std::max({Px(m_hWnd,130),TextWidth(ok_,Tr(Text::BatchExport),24),TextWidth(browse_,Tr(Text::BatchBrowse),24),TextWidth(cancel_,Tr(Text::Cancel),24)});CRect decorations(0,0,0,0);AdjustClientRect(decorations,*this);const int w=std::min(Px(m_hWnd,780),std::max(400,int(monitor.rcWork.right-monitor.rcWork.left)-decorations.Width()-gap*2)),h=std::min(Px(m_hWnd,540),std::max(390,int(monitor.rcWork.bottom-monitor.rcWork.top)-decorations.Height()-gap*2));const int lw=std::min(w/3,std::max({TextWidth(folderLabel_,Tr(Text::BatchFolder),8),TextWidth(nameLabel_,Tr(Text::BatchStem),8),TextWidth(formatLabel_,Tr(Text::BatchFormat),8),TextWidth(qualityLabel_,Tr(Text::JpegQuality),8)})),x=gap*2+lw;
    folderLabel_.MoveWindow(gap,gap,lw,row);folder_.MoveWindow(x,gap,std::max(40,w-x-bw-gap*2),row);browse_.MoveWindow(w-gap-bw,gap,bw,row);formatLabel_.MoveWindow(gap,gap*2+row,lw,row);format_.MoveWindow(x,gap*2+row,Px(m_hWnd,90),row+Px(m_hWnd,150));qualityLabel_.MoveWindow(gap,gap*3+row*2,lw,row);quality_.MoveWindow(x,gap*3+row*2,Px(m_hWnd,65),row);
    const int bottom=h-gap-row,nameY=bottom-gap-row,helpY=gap*4+row*3;const int helpSpace=nameY-helpY-gap*2-row,helpHeight=helpSpace>=row?std::min(row*2,helpSpace):0,listY=helpY+(helpHeight?helpHeight+gap:0);help_.ShowWindow(helpHeight?SW_SHOW:SW_HIDE);help_.MoveWindow(gap,helpY,w-gap*2,std::max(1,helpHeight));list_.MoveWindow(gap,listY,w-gap*2,std::max(1,nameY-gap-listY));list_.SetColumnWidth(0,(w-gap*3)/2);list_.SetColumnWidth(1,(w-gap*3)/2);nameLabel_.MoveWindow(gap,nameY,lw,row);name_.MoveWindow(x,nameY,w-x-gap,row);ok_.MoveWindow(w-gap*2-bw*2,bottom,bw,row);cancel_.MoveWindow(w-gap-bw,bottom,bw,row);CRect r(0,0,w,h);AdjustClientRect(r,*this);SetWindowPos(nullptr,0,0,r.Width(),r.Height(),SWP_NOMOVE|SWP_NOZORDER);Invalidate(TRUE);}
LRESULT BatchExportDialog::OnDpiChanged(WPARAM,LPARAM value){ScaleDialog(*this,font_,dpi_,value);Layout();return 0;}
LRESULT BatchExportDialog::OnLanguageChanged(WPARAM,LPARAM){RefreshBoundText(m_hWnd);for(int i=0;i<2;++i){CString text=Tr(i?Text::BatchOutputName:Text::BatchPages);LVCOLUMN column{};column.mask=LVCF_TEXT;column.pszText=text.GetBuffer();list_.SetColumn(i,&column);text.ReleaseBuffer();}Layout();return 0;}
